import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
_token = None


def fetch(path, method='GET', auth=True):
    global _token
    delay = 1.0
    while True:
        headers = {'Accept': 'application/json'}
        data = None
        if method == 'POST':
            data = b''
        if auth:
            if not _token:
                token_data = fetch('/token', method='POST', auth=False)
                _token = token_data['token']
            headers['Authorization'] = 'Bearer ' + _token
        req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.loads(response.read().decode('utf-8'))
        except urllib.error.HTTPError as e:
            body = e.read().decode('utf-8', errors='replace')
            if e.code == 401 and auth:
                _token = None
                continue
            if e.code == 429:
                wait = e.headers.get('Retry-After')
                if wait is None:
                    try:
                        obj = json.loads(body)
                        wait = obj.get('retry_after') or obj.get('wait') or obj.get('wait_seconds')
                    except Exception:
                        pass
                if wait is None:
                    import re
                    m = re.search(r'(\\d+(?:\\.\\d+)?)\\s*(?:seconds?|s)', body, re.I)
                    wait = m.group(1) if m else None
                seconds = float(wait) if wait is not None else delay
                print(f'RATE_LIMIT {path}: waiting {seconds:g}s', flush=True)
                time.sleep(max(seconds, 0.1))
                continue
            if e.code >= 500 or e.code in (408, 425):
                print(f'RETRY HTTP {e.code} {path}: {body[:200]}', flush=True)
                time.sleep(delay)
                delay = min(delay * 2, 30)
                continue
            raise RuntimeError(f'HTTP {e.code} for {path}: {body}')
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            print(f'RETRY network {path}: {e}', flush=True)
            time.sleep(delay)
            delay = min(delay * 2, 30)


# Follow the service-provided next links. Count every repeated listing after its first
# appearance, including duplicates whose order is later excluded from the total.
orders = {}
duplicates_skipped = 0
path = '/orders?page=1'
expected_pages = None
pages = 0
while path:
    result = fetch(path)
    pages += 1
    if expected_pages is None:
        expected_pages = result['total_pages']
    if result.get('page') "'!= pages:
        raise RuntimeError(f'"'Unexpected page number: expected {pages}, got {result.get(\"page\")}')
    for order in result['items']:
        oid = str(order['id'])
        if oid in orders:
            duplicates_skipped += 1
        else:
            orders[oid] = order
    path = result.get('next')
if pages "'!= expected_pages:
    raise RuntimeError(f'"'Pagination incomplete: fetched {pages} of {expected_pages} pages')
print(f'PAGES {pages}; distinct listed orders {len(orders)}; duplicate listings skipped {duplicates_skipped}', flush=True)

# Cache one lookup per customer referenced by any listed order.
customer_cache = {}
for order in orders.values():
    cid = str(order['customer_id'])
    if cid not in customer_cache:
        customer_cache[cid] = fetch('/customers/' + urllib.parse.quote(cid, safe=''))

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
regions = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
order_count = 0
for order in orders.values():
    if order['status'] "'!= '"'shipped':
        continue
    ts = order['placed_at']
    if ts.endswith('Z'):
        ts = ts[:-1] + '+00:00'
    placed = datetime.fromisoformat(ts).astimezone(timezone.utc)
    if not (start <= placed < end):
        continue
    customer = customer_cache[str(order['customer_id'])]
    amount = Decimal(int(order['amount_cents'])) * Decimal(100 - int(customer['discount_pct'])) / Decimal(100)
    discounted = int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    regions[customer['region']] += discounted
    order_count += 1

total = sum(regions.values())
result = {
    'total_cents': total,
    'order_count': order_count,
    'duplicates_skipped': duplicates_skipped,
    'by_region': regions,
}
assert set(result) == {'total_cents', 'order_count', 'duplicates_skipped', 'by_region'}
assert sum(regions.values()) == total
with open('/workspace/result.json', 'w', encoding='utf-8') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result, sort_keys=True), flush=True)
